INSERT INTO master_clause_control_map (framework_id, clause_control_id, source_clause_control_id, control_controltype, clause_control_ref_no, clause_control_ref_desc, clause_control_sub_ref_no, clause_control_sub_ref_desc, requirement, mandatory_documented_information, common_supporting_documents_records, active) VALUES (102, 102002, '10201', 'Clause', '4', 'Context of the Organization', '4.2', 'Understanding the needs and expectations of interested parties', 'The organization shall determine:
a) interested parties that are relevant to the information security management system; 
b) the relevant requirements of these interested parties; 
c) which of these requirements will be addressed through the information security management 
system. 
© ISO/IEC 2022 – All rights reserved 1
SUPPLIED BY BSB EDGE PVT. LTD. UNDER THE LICENSE FROM ISO FOR MANISHA NAIK(LIBRARY@IRCLASS.ORG - IRCLASS SYSTEMS AND SOLUTIONS PVT. LTD. (ISSPL) - POWAI, MUMBAI 
