INSERT INTO master_clause_control_map (framework_id, clause_control_id, source_clause_control_id, control_controltype, clause_control_ref_no, clause_control_ref_desc, clause_control_sub_ref_no, clause_control_sub_ref_desc, requirement, mandatory_documented_information, common_supporting_documents_records, active) VALUES (102, 102003, '10201', 'Clause', '4', 'Context of the Organization', '4.3', 'Determining the scope of the information security management system', 'The organization shall determine the boundaries and applicability of the information security 
management system to establish its scope.
When determining this scope, the organization shall consider:
a) the external and internal issues referred to in 4.1;
b) the requirements referred to in 4.2; 
c) interfaces and dependencies between activities performed by the organization, and those that are 
performed by other organizations.
The scope shall be available as documented information.', 'ISMS Scope Document', 'Scope Statement, Network Diagram, Organization Structure', TRUE);
INSERT INTO master_clause_control_map (framework_id, clause_control_id, source_clause_control_id, control_controltype, clause_control_ref_no, clause_control_ref_desc, clause_control_sub_ref_no, clause_control_sub_ref_desc, requirement, mandatory_documented_information, common_supporting_documents_records, active) VALUES (102, 102004, '10201', 'Clause', '4', 'Context of the Organization', '4.4', 'Information security management system', 'The organization shall establish, implement, maintain and continually improve an information security 
management system, including the processes needed and their interactions, in accordance with the 
requirements of this document.', 'Evidence that ISMS is established, implemented and maintained', 'ISMS Manual, Process Interaction Map', TRUE);
INSERT INTO master_clause_control_map (framework_id, clause_control_id, source_clause_control_id, control_controltype, clause_control_ref_no, clause_control_ref_desc, clause_control_sub_ref_no, clause_control_sub_ref_desc, requirement, mandatory_documented_information, common_supporting_documents_records, active) VALUES (102, 102005, '10202', 'Clause', '5', 'Leadership', '5.1', 'Leadership & Commitment', 'Top management shall demonstrate leadership and commitment with respect to the information 
security management system by:
a) ensuring the information security policy and the information security objectives are established 
and are compatible with the strategic direction of the organization;
b) ensuring the integration of the information security management system requirements into the 
organization’s processes;
c) ensuring that the resources needed for the information security management system are available;
d) communicating the importance of effective information security management and of conforming 
to the information security management system requirements;
e) ensuring that the information security management system achieves its intended outcome(s);
f) directing and supporting persons to contribute to the effectiveness of the information security 
management system;
g) promoting continual improvement; and
h) supporting other relevant management roles to demonstrate their leadership as it applies to their 
areas of responsibility.
NOTE Reference to “business” in this document can be interpreted broadly to mean those activities that are 
core to the purposes of the organization’s existence.', 'Evidence of leadership commitment', 'Meeting Minutes, Resource Allocation Records', TRUE);
INSERT INTO master_clause_control_map (framework_id, clause_control_id, source_clause_control_id, control_controltype, clause_control_ref_no, clause_control_ref_desc, clause_control_sub_ref_no, clause_control_sub_ref_desc, requirement, mandatory_documented_information, common_supporting_documents_records, active) VALUES (102, 102006, '10202', 'Clause', '5', 'Leadership', '5.2', 'Information Security Policy', 'Top management shall establish an information security policy that:
a) is appropriate to the purpose of the organization;
b) includes information security objectives (see 6.2) or provides the framework for setting information 
security objectives;
c) includes a commitment to satisfy applicable requirements related to information security; 
d) includes a commitment to continual improvement of the information security management system.
The information security policy shall:
e) be available as documented information;
f) be communicated within the organization; 
g) be available to interested parties, as appropriate.', 'Information Security Policy', 'Security Objectives, Supporting Policies', TRUE);
INSERT INTO master_clause_control_map (framework_id, clause_control_id, source_clause_control_id, control_controltype, clause_control_ref_no, clause_control_ref_desc, clause_control_sub_ref_no, clause_control_sub_ref_desc, requirement, mandatory_documented_information, common_supporting_documents_records, active) VALUES (102, 102007, '10202', 'Clause', '5', 'Leadership', '5.3', 'Organizational Roles & Responsibilities', 'Top management shall ensure that the responsibilities and authorities for roles relevant to information 
security are assigned and communicated within the organization.
Top management shall assign the responsibility and authority for:
a) ensuring that the information security management system conforms to the requirements of this 
document; 
b) reporting on the performance of the information security management system to top management.
NOTE Top management can also assign responsibilities and authorities for reporting performance of the 
information security management system within the organization.', 'Evidence of assigned responsibilities', 'Organization Chart, RACI Matrix, Job Descriptions', TRUE);
INSERT INTO master_clause_control_map (framework_id, clause_control_id, source_clause_control_id, control_controltype, clause_control_ref_no, clause_control_ref_desc, clause_control_sub_ref_no, clause_control_sub_ref_desc, requirement, active) VALUES (102, 102008, '10203', 'Clause', '6', 'Planning', '6.1', 'Actions to address risks and opportunities', 'Actions to address risks and opportunities', TRUE);
INSERT INTO master_clause_control_map (framework_id, clause_control_id, source_clause_control_id, control_controltype, clause_control_ref_no, clause_control_ref_desc, clause_control_sub_ref_no, clause_control_sub_ref_desc, requirement, mandatory_documented_information, common_supporting_documents_records, active) VALUES (102, 102009, '10203', 'Clause', '6', 'Planning', '6.1.1', 'Risk Management', 'When planning for the information security management system, the organization shall consider 
the issues referred to in 4.1 and the requirements referred to in 4.2 and determine the risks and 
opportunities that need to be addressed to:
a) ensure the information security management system can achieve its intended outcome(s);
b) prevent, or reduce, undesired effects; 
c) achieve continual improvement.
The organization shall plan:
d) actions to address these risks and opportunities; and
e) how to
1) integrate and implement the actions into its information security management system 
processes; and
2) evaluate the effectiveness of these actions.', 'Risk Management Process', 'Risk Management Methodology', TRUE);
INSERT INTO master_clause_control_map (framework_id, clause_control_id, source_clause_control_id, control_controltype, clause_control_ref_no, clause_control_ref_desc, clause_control_sub_ref_no, clause_control_sub_ref_desc, requirement, mandatory_documented_information, common_supporting_documents_records, active) VALUES (102, 102010, '10203', 'Clause', '6', 'Planning', '6.1.2', 'Information Security Risk Assessment', 'The organization shall define and apply an information security risk assessment process that:
a) establishes and maintains information security risk criteria that include:
1) the risk acceptance criteria; and
2) criteria for performing information security risk assessments;
b) ensures that repeated information security risk assessments produce consistent, valid and 
comparable results;
c) identifies the information security risks:
1) apply the information security risk assessment process to identify risks associated with 
the loss of confidentiality, integrity and availability for information within the scope of the 
information security management system; and
2) identify the risk owners;
d) analyses the information security risks:
1) assess the potential consequences that would result if the risks identified in 6.1.2 c) 1) were to 
materialize;
2) assess the realistic likelihood of the occurrence of the risks identified in 6.1.2 c) 1); and
3) determine the levels of risk;
e) evaluates the information security risks:
1) compare the results of risk analysis with the risk criteria established in 6.1.2 a); and
2) prioritize the analysed risks for risk treatment.
The organization shall retain documented information about the information security risk assessment 
process.', 'Risk Assessment Process', 'Risk Assessment Report, Risk Register', TRUE);
INSERT INTO master_clause_control_map (framework_id, clause_control_id, source_clause_control_id, control_controltype, clause_control_ref_no, clause_control_ref_desc, clause_control_sub_ref_no, clause_control_sub_ref_desc, requirement, mandatory_documented_information, common_supporting_documents_records, active) VALUES (102, 102011, '10203', 'Clause', '6', 'Planning', '6.1.3', 'Risk Treatment', 'The organization shall define and apply an information security risk treatment process to:
a) select appropriate information security risk treatment options, taking account of the risk 
assessment results;
b) determine all controls that are necessary to implement the information security risk treatment 
option(s) chosen;
NOTE 1 Organizations can design controls as required, or identify them from any source.
c) compare the controls determined in 6.1.3 b) above with those in Annex A and verify that no 
necessary controls have been omitted;
NOTE 2 Annex A contains a list of possible information security controls. Users of this document are 
directed to Annex A to ensure that no necessary information security controls are overlooked.
NOTE 3 The information security controls listed in Annex A are not exhaustive and additional information 
security controls can be included if needed.
d) produce a Statement of Applicability that contains:
— justification for their inclusion;
— whether the necessary controls are implemented or not; and
— the justification for excluding any of the Annex A controls.
e) formulate an information security risk treatment plan; and
f) obtain risk owners’ approval of the information security risk treatment plan and acceptance of the 
residual information security risks.
The organization shall retain documented information about the information security risk treatment 
process.
NOTE 4 The information security risk assessment and treatment process in this document aligns with the 
principles and generic guidelines provided in ISO 31000[5].', 'Risk Treatment Process', 'Risk Treatment Plan', TRUE);
