INSERT INTO master_clause_control_map (framework_id, clause_control_id, source_clause_control_id, control_controltype, clause_control_ref_no, clause_control_ref_desc, clause_control_sub_ref_no, clause_control_sub_ref_desc, requirement, mandatory_documented_information, common_supporting_documents_records, active) VALUES (102, 102034, '10207', 'Clause', '10', 'Improvement', '10.2', 'Nonconformity & Corrective Action', 'When a nonconformity occurs, the organization shall:
a) react to the nonconformity, and as applicable:
1) take action to control and correct it; 
2) deal with the consequences;
b) evaluate the need for action to eliminate the causes of nonconformity, in order that it does not recur 
or occur elsewhere, by:
1) reviewing the nonconformity;
2) determining the causes of the nonconformity; and
3) determining if similar nonconformities exist, or could potentially occur;
c) implement any action needed;
d) review the effectiveness of any corrective action taken; and
e) make changes to the information security management system, if necessary.
Corrective actions shall be appropriate to the effects of the nonconformities encountered.
Documented information shall be available as evidence of: 
f) the nature of the nonconformities and any subsequent actions taken, 
g) the results of any corrective action.', 'Corrective Action Results', 'NCR Register, Root Cause Analysis, CAPA Records', TRUE);
